func runList(args []string) int {
	fs := flag.NewFlagSet("list", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	specPath := fs.String("spec", "", "path to spec file")
	format := fs.String("format", "text", "output format: json|text")
	only := fs.String("only", "", "comma-separated list of job names")
	if err := fs.Parse(args); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}
	if *specPath == "" {
		fmt.Fprintln(os.Stderr, "error: missing --spec")
		return 2
	}
	if len(fs.Args()) > 0 {
		fmt.Fprintf(os.Stderr, "error: unexpected argument: %s\n", fs.Args()[0])
		return 2
	}
	if *format != "text" && *format != "json" {
		fmt.Fprintln(os.Stderr, "error: bad --format")
		return 2
	}

	spec, err := loadSpec(*specPath)
	if err != nil {
		printValidationError(err)
		return 2
	}

	selected, err := parseOnlyFilter(spec, *only)
	if err != nil {
		printValidationError(err)
		return 2
	}

	jobs, levels := listJobs(spec, selected)
	switch *format {
	case "text":
		os.Stdout.Write(renderListText(jobs, levels))
	case "json":
		os.Stdout.Write(renderListJSON(*specPath, jobs, levels))
	}
	return 0
}

func parseOnlyFilter(spec *Spec, only string) (map[string]bool, error) {
	if only == "" {
		return nil, nil
	}

	selected := map[string]bool{}
	seen := map[string]bool{}
	for _, name := range strings.Split(only, ",") {
		if seen[name] {
			continue
		}
		seen[name] = true

		job, ok := spec.ByName[name]
		if !ok {
			return nil, &ValidationError{Code: "unknown_dep", Message: "unknown dep in --only: " + name}
		}
		addTransitiveDeps(spec, job, selected)
	}
	return selected, nil
}

func addTransitiveDeps(spec *Spec, job *Job, selected map[string]bool) {
	if selected[job.Name] {
		return
	}
	selected[job.Name] = true
	for _, dep := range job.Deps {
		addTransitiveDeps(spec, spec.ByName[dep], selected)
	}
}

func listJobs(spec *Spec, selected map[string]bool) ([]*Job, map[string]int) {
	levels := computeLevels(spec)
	level := make(map[string]int, len(spec.Jobs))
	for i, names := range levels {
		for _, name := range names {
			level[name] = i
		}
	}

	order := make([]*Job, 0, len(spec.Jobs))
	for _, names := range levels {
		for _, name := range names {
			if selected != nil && !selected[name] {
				continue
			}
			order = append(order, spec.ByName[name])
		}
	}
	return order, level
}

func renderListText(jobs []*Job, level map[string]int) []byte {
	var b strings.Builder
	for _, job := range jobs {
		b.WriteString(job.Name)
		b.WriteString("\tlevel=")
		b.WriteString(strconv.Itoa(level[job.Name]))
		b.WriteString("\tworkdir=")
		b.WriteString(job.Workdir)
		b.WriteString("\tdeps=")
		b.WriteString(strings.Join(job.Deps, ","))
		b.WriteString("\tenv=")
		b.WriteString(renderEnvText(job.Env))
		b.WriteString("\n")
	}
	return []byte(b.String())
}

func renderEnvText(env map[string]string) string {
	if len(env) == 0 {
		return ""
	}
	keys := make([]string, 0, len(env))
	for k := range env {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, len(keys))
	for i, k := range keys {
		parts[i] = k + "=" + env[k]
	}
	return strings.Join(parts, ",")
}

func renderListJSON(specPath string, jobs []*Job, level map[string]int) []byte {
	var b bytes.Buffer
	b.WriteString(`{"spec_path":"`)
	writeJSONString(&b, specPath)
	b.WriteString(`","count":`)
	b.WriteString(strconv.Itoa(len(jobs)))
	b.WriteString(`,"jobs":[`)
	for i, job := range jobs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"name":"`)
		writeJSONString(&b, job.Name)
		b.WriteString(`","level":`)
		b.WriteString(strconv.Itoa(level[job.Name]))
		b.WriteString(`,"workdir":"`)
		writeJSONString(&b, job.Workdir)
		b.WriteString(`","deps":`)
		writeDepsJSON(&b, job.Deps)
		b.WriteString(`,"env":`)
		writeEnvJSON(&b, job.Env)
		b.WriteString(`,"command":"`)
		writeJSONString(&b, job.Command)
		b.WriteString(`"}`)
	}
	b.WriteString(`]}`)
	b.WriteByte('\n')
	return b.Bytes()
}

func writeDepsJSON(b *bytes.Buffer, deps []string) {
	b.WriteByte('[')
	for i, dep := range deps {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('"')
		writeJSONString(b, dep)
		b.WriteByte('"')
	}
	b.WriteByte(']')
}

func writeEnvJSON(b *bytes.Buffer, env map[string]string) {
	b.WriteByte('{')
	if len(env) > 0 {
		keys := make([]string, 0, len(env))
		for k := range env {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for i, k := range keys {
			if i > 0 {
				b.WriteByte(',')
			}
			b.WriteByte('"')
			writeJSONString(b, k)
			b.WriteString(`":"`)
			writeJSONString(b, env[k])
			b.WriteByte('"')
		}
	}
	b.WriteByte('}')
}

func printValidationError(err error) {
	if ve, ok := err.(*ValidationError); ok {
		fmt.Fprintf(os.Stderr, "error: %s: %s\n", ve.Code, ve.Message)
		return
	}
	fmt.Fprintf(os.Stderr, "error: %s\n", err)
}
